```javascript
// Using a Hash Map for O(1) lookups
function interviewFunctions(nums, target) {
  const map = new Map();
  for(let i=0; i<nums.length; i++) {
    const complement = target - nums[i];
    if (map.has(complement)) {
      return [map.get(complement), i];
    }
    map.set(nums[i], i);
  }
  return [-1, -1];
}
```

