// Advanced / Recursive / Divide & Conquer approach
function advancedFunctions(data, left, right) {
  if (left >= right) return;
  const mid = Math.floor((left + right) / 2);
  // Process left
  advancedFunctions(data, left, mid);
  // Process right
  advancedFunctions(data, mid + 1, right);
  // Merge step...
}
```
Reduces time complexity to O(N log N) in sorting scenarios.

