// Bitwise / Two Pointer / Optimal approach
function expertFunctions(nums) {
  let slow = 0;
  let fast = 0;
  while (fast < nums.length) {
    if (nums[fast] !== 0) {
      // Swap
      [nums[slow], nums[fast]] = [nums[fast], nums[slow]];
      slow++;
    }
    fast++;
  }
  return nums;
}
```
This modifies the array strictly in-place with zero extra memory allocations.
